function draw({svg,width,height,progress,params,state,controls}){
 const NS='http://www.w3.org/2000/svg', ink='#283b42', muted='#65777b', teal='#167c80', blue='#4669af', orange='#bd6b35';
 function el(tag,id,attrs={},txt){let n=svg.querySelector('[data-k="'+id+'"]');if(!n){n=document.createElementNS(NS,tag);n.setAttribute('data-k',id);svg.appendChild(n);}for(const [k,v] of Object.entries(attrs))n.setAttribute(k,String(v));if(txt!==undefined)n.textContent=txt;return n;}
 function line(id,x1,y1,x2,y2,c=muted,sw=1,dash=''){return el('line',id,{x1,y1,x2,y2,stroke:c,'stroke-width':sw,'stroke-dasharray':dash});}
 function text(id,x,y,s,c=ink,size=14,anchor='start'){return el('text',id,{x,y,fill:c,'font-size':size,'font-family':'system-ui, sans-serif','text-anchor':anchor},s);}
 function path(id,d,c,sw=2,fill='none'){return el('path',id,{d,stroke:c,'stroke-width':sw,fill,'stroke-linecap':'round','stroke-linejoin':'round'});}
 function dot(id,x,y,c,r=4){return el('circle',id,{cx:x,cy:y,r,fill:c});}
 function arrow(id,x1,y1,x2,y2,c,sw=2){let visible=Math.hypot(x2-x1,y2-y1)>.01;line(id+'s',x1,y1,x2,y2,c,sw).setAttribute('opacity',visible?1:0);let a=Math.atan2(y2-y1,x2-x1),l=8;path(id+'h','M'+(x2-l*Math.cos(a-.4))+','+(y2-l*Math.sin(a-.4))+'L'+x2+','+y2+'L'+(x2-l*Math.cos(a+.4))+','+(y2-l*Math.sin(a+.4)),c,sw).setAttribute('opacity',visible?1:0);}
 const mobile=width<600, W=width,H=height;svg.setAttribute('viewBox','0 0 '+W+' '+H);

 const sign=Number(params.side||1),h=sign*.65*(1-progress),q=2+3*h,f=x=>3*x*x-4*x;
 const L=42,R=mobile?W-20:W*.62,T=77,B=mobile?H-160:H-48;
 const X=x=>L+(x-.3)/1.6*(R-L),Y=y=>B-(y+1.8)/5.3*(B-T);
 text('legend1',L,21,'曲线  f(x) = 3x² − 4x',ink,14);
 text('legend2',L,43,'切线',teal,13);line('lt',L+34,39,L+64,39,teal,2);
 text('legend3',L+88,43,'割线',orange,13);line('ls',L+122,39,L+152,39,orange,2);
 line('axisx',L,Y(0),R,Y(0),'#b4c1c3');line('axisy',L,T,L,B,'#b4c1c3');
 for(let i=0;i<4;i++){let v=[.5,1,1.5,1.8][i];line('xt'+i,X(v),B,X(v),B+4);text('xn'+i,X(v),B+21,String(v),muted,12,'middle');}
 for(let i=0;i<5;i++){let v=i-1;line('yt'+i,L-4,Y(v),L,Y(v));text('yn'+i,L-9,Y(v)+4,String(v),muted,12,'end');}
 text('ax',R-2,B+38,'x',ink,13);text('ay',L-4,T-9,'f(x)',ink,13);
 let d='';for(let i=0;i<=100;i++){let x=.3+1.6*i/100;d+=(i?'L':'M')+X(x)+','+Y(f(x));}path('curve',d,ink,2.3);
 function slopeLine(id,m,c,dash=''){let lo=Math.max(.3,1-.8/m),hi=Math.min(1.9,1+4.5/m);line(id,X(lo),Y(-1+m*(lo-1)),X(hi),Y(-1+m*(hi-1)),c,2.4,dash);}slopeLine('tangent',2,teal,'6 4');
 slopeLine('secant',q,orange);
 line('hbase',X(1),Y(-1),X(1+h),Y(-1),orange,1,'3 3');line('rise',X(1+h),Y(-1),X(1+h),Y(f(1+h)),orange,1,'3 3');
 dot('P',X(1),Y(-1),teal,5);dot('Q',X(1+h),Y(f(1+h)),orange,h===0?2:5);
 text('Ptxt',X(1)-10,Y(-1)+24,'P',teal,13);text('Qtxt',X(1+h)+9,Y(f(1+h))-10,h===0?'Q → P':'Q',orange,13);
 const tx=mobile?L:R+35,ty=mobile?B+56:106;
 text('hval',tx,ty,'h = '+h.toFixed(3),muted,15);
 text('qval',tx,ty+30,'割线斜率  '+q.toFixed(3),orange,18);
 text('target',tx,ty+61,'切线斜率  2',teal,18);
 text('err',tx,ty+94,'差值 = 3h = '+(3*h).toFixed(3),muted,14);
 return {example:'f(x)=3x²−4x, P=(1,−1)',h,secantSlope:q,tangentSlope:2,error:3*h,endpointConvention:'h=0 时使用解析极限 2；未计算 0/0',range:'仅此二次函数；不证明一般函数极限'};
}

