 for(let j=0;j<3;j++){let i=[1,3,5][j],r=Math.sqrt(i);el('ellipse','contour'+i,{cx,cy,rx:r*scale,ry:r/Math.sqrt(2)*scale,fill:'none',stroke:'#d8e3e2','stroke-width':1.2});text('level'+i,X(r*.707)+5,Y(-r*.5)+4,String(i),muted,12);}
 line('ax',X(-2.35),cy,X(2.35),cy,'#a8b9bb');line('ay',cx,Y(-2.35),cx,Y(2.35),'#a8b9bb');
 for(let i=0;i<5;i++){let v=i-2;line('xt'+i,X(v),cy-3,X(v),cy+3);text('xn'+i,X(v),cy+17,String(v),muted,12,'middle');line('yt'+i,cx-3,Y(v),cx+3,Y(v));if(v)text('yn'+i,cx-7,Y(v)+4,String(v),muted,12,'end');}
